// Todos los registros con el mismo teléfono
const items = $input.all();

if (items.length === 0) {
  return [];
}

// El registro de ESTA ejecución es el del pilot_tracking_id recibido (no "el más nuevo":
// si llegan dos leads del mismo teléfono con 1-2 seg de diferencia, los dos verían el mismo).
const trackingId = $('Webhook').first().json.body.pilot_tracking_id;
const actual = items.find(i => trackingId && i.json.pilot_tracking_id === trackingId)
  || items.reduce((ultimo, i) => new Date(i.json.created_at) > new Date(ultimo.json.created_at) ? i : ultimo);

// Duplicado: otro lead anterior del mismo teléfono creado en las últimas 24 h
// (sin contar los que ya se marcaron como duplicados).
const creado = new Date(actual.json.created_at).getTime();
const original = items.find(i =>
  i.json.id < actual.json.id &&
  !String(i.json.reason || '').startsWith('Lead duplicado') &&
  creado - new Date(i.json.created_at).getTime() <= 24 * 60 * 60 * 1000
);

// Si Ford mandó el mismo lead de Pilot dos veces, no hay que cerrarlo en Pilot (cerraría el original).
const mismoPilot = !!original && String(original.json.pilot_tracking_id || '').trim() === String(actual.json.pilot_tracking_id || '').trim();

return [{ json: { ...actual.json, duplicado_de: original ? original.json.id : null, duplicado_mismo_pilot: mismoPilot } }];

const item = $input.first().json;

// --------------------------------------------------
// NORMALIZAR TELÉFONO
// --------------------------------------------------
function normalizarTelefono(telefono) {
  // Solo dígitos, sin el 00 internacional
  let numero = String(telefono || "").replace(/\D/g, "");
  if (numero.startsWith("00")) numero = numero.slice(2);

  if (/^57\d{10}$/.test(numero)) return numero;         // Colombia con código: 573163127436
  if (/^3\d{9}$/.test(numero)) return "57" + numero;    // Celular Colombia: 3163127436 -> 573163127436
  if (/^54\d{10,11}$/.test(numero)) return numero;      // Argentina con código (pruebas): 5491131438902
  if (/^11\d{8}$/.test(numero)) return "549" + numero;  // Argentina CABA sin código (pruebas): 1131438902

  // Cualquier otro formato es inválido: no se inventa el país
  return "";
}

// --------------------------------------------------
// NORMALIZAR TELÉFONOS
// --------------------------------------------------
item.pilot_phone = normalizarTelefono(item.pilot_phone);
item.pilot_cellphone = normalizarTelefono(item.pilot_cellphone);

// --------------------------------------------------
// DATOS
// --------------------------------------------------
const nombre = item.pilot_firstname && item.pilot_lastname
  ? `${item.pilot_firstname} ${item.pilot_lastname}`
  : item.pilot_firstname || item.pilot_lastname || "No aclarado";

const modelo = item.pilot_product_of_interest || "No aclarado";

const imagen = "ford_mensajeria_20261002_102302.jpg";

const idQuery = String(item.id || "0");

// --------------------------------------------------
// CONTENT VARIABLES
// --------------------------------------------------
const variables = {
  "1": nombre,
  "2": modelo,
  "3": imagen,
  "4": idQuery
};

// --------------------------------------------------
// TEMPLATE
// --------------------------------------------------
const template_id = "HXf38f3e15f4a1f8617f8391a999b4da98"; // bienvenida, también para los que salen de la cola

// --------------------------------------------------
// DEVOLVER
// --------------------------------------------------
return [
  {
    json: {
      ContentVariables: JSON.stringify(variables),
      template_id: template_id,

      // Mantener todos los datos originales
      ...item,

      debug: {
        nombreOriginal: nombre,
        modeloOriginal: modelo,
        imagenSeleccionada: imagen,
        idQuery: idQuery,
        telefono: item.pilot_cellphone || item.pilot_phone || ""
      }
    }
  }
];

