const items = $input.all();

return items.map(item => {
  const data = item.json;

  const contacto = 'contacto@grupoobc.com.co';
  const contacto1 = 'contacto1@grupoobc.com.co';

  // Si ya tiene asignación, alternar
  if (data.asignacion === contacto) {
    data.asignacion = contacto1;
  } 
  else if (data.asignacion === contacto1) {
    data.asignacion = contacto;
  } 
  // Si es null, vacío o no existe, elegir aleatoriamente
  else if (
    data.asignacion === null ||
    data.asignacion === undefined ||
    String(data.asignacion).trim() === ''
  ) {
    data.asignacion = Math.random() < 0.5
      ? contacto
      : contacto1;
  }

  return {
    json: data
  };
});

